(80552, 0, 1, 'Fire! Get it off me!', 14, 0, 100, 0, 0, 0, 0, 0, 0, 0, 'Grom''kar Siegesmith - On fire'),
(80552, 0, 2, 'Water! WATER!', 14, 0, 100, 0, 0, 0, 0, 0, 0, 0, 'Grom''kar Siegesmith - On fire');
